#!/usr/bin/env bash
# The v0 proof gate.
#
# Runs gnatprove over the SPARK-owned core and fails unless the result is a
# real proof, not merely a green exit status.
#
# Why the exit status is not enough: a project whose SPARK units are not in the
# compile closure produces
#
#     warning: no checks generated by GNATprove
#     ...and exits 0
#
# That is a vacuous pass. It is what `gnatprove -P iris_wm.gpr` does today,
# because the compositor's main is still `null` and nothing references the
# geometry package. A gate built on `$?` would have reported success while
# proving nothing, which is precisely the failure this project satirises.
#
# So this script asserts on the check table instead:
#
#   1. gnatprove exits 0
#   2. Functional Contracts is non-zero   <- the proofs are about something
#   3. Unproved is zero                   <- nothing was given up on
#   4. no "no checks generated" warning
#
# Usage:
#   scripts/prove.sh              # prove, assert, print the table
#   scripts/prove.sh --verbose    # also print every check

set -u -o pipefail

REPO="$(cd "$(dirname "$0")/.." && pwd)"
PROJECT="$REPO/tests/spark_proofs.gpr"
SUMMARY="$REPO/obj/spark/gnatprove/gnatprove.out"

# Minimum number of functional contracts. This is a floor, not a target: it is
# raised deliberately when a new SPARK unit lands, never lowered to make a
# failing run pass.
MINIMUM_FUNCTIONAL_CONTRACTS=3

failures=0

pass() { printf 'ok:   %s\n' "$1"; }
fail() { printf 'FAIL: %s\n' "$1"; failures=$((failures + 1)); }

# Locate gnatprove. It is not on PATH when Alire manages the toolchain, and it
# is deliberately not a dependency of the crate manifest.
GNATPROVE=""
if command -v gnatprove >/dev/null 2>&1; then
	GNATPROVE="$(command -v gnatprove)"
elif [ -n "${GNATPROVE_ALIRE_PREFIX:-}" ] && [ -x "$GNATPROVE_ALIRE_PREFIX/bin/gnatprove" ]; then
	GNATPROVE="$GNATPROVE_ALIRE_PREFIX/bin/gnatprove"
else
	# `alr install` puts binaries in one of two places depending on how the
	# settings directory is configured, and neither is on PATH:
	#   ~/.alire/bin/gnatprove                                  (default)
	#   ~/.local/share/alire/releases/gnatprove_*/bin/gnatprove (custom settings dir)
	# Verified in a clean debian:bookworm-slim container: `alr install
	# gnatprove=16.1.0` reports success and lands in /root/.alire/bin.
	for candidate in "$HOME"/.alire/bin/gnatprove \
	                 "$HOME"/.local/share/alire/releases/gnatprove_*/bin/gnatprove \
	                 "$HOME"/.alire/releases/gnatprove_*/bin/gnatprove; do
		if [ -x "$candidate" ]; then
			GNATPROVE="$candidate"
			break
		fi
	done
fi

if [ -z "$GNATPROVE" ]; then
	echo "FAIL: gnatprove not found."
	echo "      Install it pinned: alr install gnatprove=16.1.0"
	exit 1
fi
printf 'using %s (%s)\n\n' "$GNATPROVE" "$("$GNATPROVE" --version 2>&1 | head -1)"

if [ ! -f "$PROJECT" ]; then
	echo "FAIL: $PROJECT missing"
	exit 1
fi

rm -rf "$REPO/obj/spark"
mkdir -p "$REPO/obj"

VERBOSE=""
if [ "${1:-}" = "--verbose" ]; then
	VERBOSE="--output-msg-only"
fi

# --proof=per_check:all is mandatory. Without it the summary omits checks that
# were generated, which is how a real proof can look like a vacuous one and
# vice versa.
set +e
"$GNATPROVE" -P "$PROJECT" \
	--mode=all \
	--level=4 \
	--proof=per_check:all \
	$VERBOSE 2>&1 | tee "$REPO/obj/spark-gnatprove.log" | grep -vE '^Phase [0-9] of [0-9]'
PROVE_STATUS=${PIPESTATUS[0]}
set -e

echo

if [ "$PROVE_STATUS" -eq 0 ]; then
	pass "gnatprove exited 0"
else
	fail "gnatprove exited $PROVE_STATUS"
fi

if grep -q "no checks generated" "$REPO/obj/spark-gnatprove.log"; then
	fail "gnatprove generated no checks at all"
	echo "      the SPARK units are probably not in the compile closure;"
	echo "      check that their bodies are listed in tests/spark_proofs.gpr"
fi

if [ ! -f "$SUMMARY" ]; then
	fail "no summary at $SUMMARY"
else
	# The summary lines look like:
	#   Functional Contracts              3          .    3 (CVC5 ...)  .  .
	#   Total                            10    3 (30%)      7 (70%)     .  .
	# and with failures:
	#   Total                            10    3 (30%)      6 (60%)     .    1 (10%)
	#
	# awk splits "Functional Contracts" into two fields, so $3 is the TOTAL
	# column there. On the Total row the unproved count is the second-to-last
	# field and the percentage is last, so $NF-1 is the count and $NF is only
	# a percentage. Reading $NF would compare "(10%)" against 0.
	FUNCTIONAL=$(awk '/^Functional Contracts/ && $3 ~ /^[0-9]+$/ { print $3; exit }' "$SUMMARY")

	UNPROVED=$(awk '/^Total/ && $2 ~ /^[0-9]+$/ {
		if (NF >= 2 && $(NF-1) ~ /^[0-9]+$/ && $NF ~ /^\(/) print $(NF-1);
		else if ($NF ~ /^[0-9]+$/) print $NF;
		else print 0;
		exit
	}' "$SUMMARY")

	FUNCTIONAL=${FUNCTIONAL:-0}
	UNPROVED=${UNPROVED:-0}
	if [ "$UNPROVED" = "." ]; then
		UNPROVED=0
	fi

	printf 'functional contracts: %s (minimum %s)\n' \
		"$FUNCTIONAL" "$MINIMUM_FUNCTIONAL_CONTRACTS"
	printf 'unproved:             %s\n\n' "$UNPROVED"

	if [ "$FUNCTIONAL" -ge "$MINIMUM_FUNCTIONAL_CONTRACTS" ] 2>/dev/null; then
		pass "functional contracts >= $MINIMUM_FUNCTIONAL_CONTRACTS"
	else
		fail "functional contracts is $FUNCTIONAL, expected >= $MINIMUM_FUNCTIONAL_CONTRACTS"
	fi

	if [ "$UNPROVED" -eq 0 ] 2>/dev/null; then
		pass "no unproved checks"
	else
		fail "$UNPROVED unproved check(s)"
	fi
fi

echo
if [ "$failures" -eq 0 ]; then
	echo "RESULT: PASS"
	echo
	echo "v0's SPARK gate is satisfied by this run."
	exit 0
fi

echo "RESULT: FAIL ($failures failing checks)"
exit 1
